using System;
using System.Reflection;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using NUnit.Framework;
using STP.Application;

namespace STP.Tests.Application.EditMode
{
    public sealed class PersistedPuzzleSessionTests
    {
        private sealed class ControlledDispatcher : ILocalSaveDispatcher
        {
            internal bool HoldNext;internal int SkipBeforeHold;private Action? pending;private TaskCompletionSource<bool>? acknowledgement;internal readonly TaskCompletionSource<bool> Held=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
            public Task InvokeAsync(Action action){if(!HoldNext||SkipBeforeHold-->0){action();return Task.CompletedTask;}HoldNext=false;pending=action;acknowledgement=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);Held.TrySetResult(true);return acknowledgement.Task;}
            internal void Release(){pending!();acknowledgement!.SetResult(true);pending=null;}
        }
        private static async Task<(LocalSaveContractFixtures.Setup Setup,PersistedPuzzleSession Use,LocalSaveContractFixtures.Repository Repo,LocalSaveContractFixtures.Clock Clock)> Ready(ILocalSaveDispatcher dispatcher)
        {var s=new LocalSaveContractFixtures.Setup();var clock=new LocalSaveContractFixtures.Clock();var repo=new LocalSaveContractFixtures.Repository{Loaded=SaveLoadResult<LocalProfileState>.Success(new SaveSnapshot<LocalProfileState>(s.Profile,s.Aggregate,1,s.Empty),s.Observe())};var use=new PersistedPuzzleSession(repo,s.Puzzles,s.Policy,s.Profile,s.Catalogs,clock,dispatcher);await use.LoadAsync(CancellationToken.None);return(s,use,repo,clock);}
        [Test]
        public async Task CompletionAcknowledgementCannotReleaseResultsForAnotherStartedOrRestoredAttempt()
        {
            var f=await Ready(new ControlledDispatcher());LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[0].Identity,Guid.NewGuid());LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);var ack=new TaskCompletionSource<SaveCommitResult<LocalProfileState>>(TaskCreationOptions.RunContinuationsAsynchronously);var entered=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);f.Repo.OnCommit=(s,g,ct)=>{entered.TrySetResult(true);return ack.Task;};var task=f.Use.CommitCompletionAsync(CancellationToken.None);await entered.Task;Assert.That(task.IsCompleted,Is.False);Assert.That(f.Use.CanPresentResults,Is.False);var solvedBefore=LocalSaveContractFixtures.Get(f.Use,"Session");var startError=Assert.Throws<TargetInvocationException>(()=>LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[1].Identity,Guid.NewGuid()));Assert.That(startError!.InnerException!.Message,Is.EqualTo("SAVE_USE_CASE_BLOCKED"));Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.SameAs(solvedBefore));var restoreError=Assert.Throws<TargetInvocationException>(()=>LocalSaveContractFixtures.Call(f.Use,"RestoreDraft",f.Setup.Puzzles.Puzzles[1].Identity));Assert.That(restoreError!.InnerException!.Message,Is.EqualTo("SAVE_USE_CASE_BLOCKED"));Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.SameAs(solvedBefore));ack.SetResult(SaveCommitResult<LocalProfileState>.Success(f.Repo.LastOffered!));await task;Assert.That(f.Use.CanPresentResults,Is.True);LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[1].Identity,Guid.NewGuid());Assert.That(f.Use.CanPresentResults,Is.False);
        }
        [Test]
        public async Task DelayedAlreadyCommittedPublicationCannotAcknowledgeNewSolvedAttempt()
        {
            var dispatcher=new ControlledDispatcher();var f=await Ready(dispatcher);LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[0].Identity,Guid.NewGuid());LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);await f.Use.CommitCompletionAsync(CancellationToken.None);Assert.That(f.Use.CanPresentResults,Is.True);dispatcher.HoldNext=true;dispatcher.SkipBeforeHold=1;var replay=f.Use.CommitCompletionAsync(CancellationToken.None);await dispatcher.Held.Task;Assert.That(replay.IsCompleted,Is.False);LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[1].Identity,Guid.NewGuid());LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);dispatcher.Release();await replay;Assert.That(f.Use.CanPresentResults,Is.False,"An old attempt acknowledgement must not grant results to the newly solved attempt");Assert.That(f.Repo.Commits,Is.EqualTo(1));
        }
        [Test]
        public async Task BothStickyMarkersDoNotPenalizeNullTimeStarsOrFirstClearCurrency()
        {var f=await Ready(new ControlledDispatcher());LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[0].Identity,Guid.NewGuid());LocalSaveContractFixtures.Mark(f.Use,f.Clock,100,"MARK_EMPTY",0);LocalSaveContractFixtures.Mark(f.Use,f.Clock,101,"MARK_OCCUPIED",10);LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);await f.Use.CommitCompletionAsync(CancellationToken.None);var level=f.Use.Snapshot!.Payload.Levels[0];Assert.That(level.DirectSolved,Is.False);Assert.That(level.StarsHighWater,Is.EqualTo(1));Assert.That(f.Setup.Ledger.Validate(f.Use.Snapshot.Payload),Is.EqualTo(15));}
        [Test]
        public async Task ExplicitCompletionFailureRetainsSolvedAttemptAndRetryPaysExactlyOnceAfterConfirmedAck()
        {
            var f=await Ready(new ControlledDispatcher());var identity=f.Setup.Puzzles.Puzzles[0].Identity;LocalSaveContractFixtures.Call(f.Use,"Start",identity,Guid.NewGuid());LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);var solved=LocalSaveContractFixtures.Get(f.Use,"Session");var durable=f.Use.Snapshot;f.Repo.OnCommit=(s,g,ct)=>Task.FromResult(SaveCommitResult<LocalProfileState>.Failure(SaveCommitStatus.Failed,"SAVE_TEST_FAILED_BEFORE_WRITE"));Assert.That((await f.Use.CommitCompletionAsync(CancellationToken.None)).Succeeded,Is.False);Assert.That(f.Use.Snapshot,Is.SameAs(durable));Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.SameAs(solved));Assert.That(f.Use.CanPresentResults||f.Use.CanMutate,Is.False);Assert.That(f.Setup.Ledger.Validate(durable!.Payload),Is.Zero);f.Repo.OnCommit=null;Assert.That((await f.Use.CommitCompletionAsync(CancellationToken.None)).Succeeded,Is.True);Assert.That(f.Use.CanPresentResults,Is.True);Assert.That(f.Setup.Ledger.Validate(f.Use.Snapshot!.Payload),Is.EqualTo(15));Assert.That(f.Use.Snapshot.Payload.Levels.Count(l=>l.FirstClear!=null),Is.EqualTo(1));Assert.That((await f.Use.CommitCompletionAsync(CancellationToken.None)).Succeeded,Is.True);Assert.That(f.Repo.Commits,Is.EqualTo(2));Assert.That(f.Setup.Ledger.Validate(f.Use.Snapshot.Payload),Is.EqualTo(15));
        }
        [Test]
        public async Task CommitDurableBeforeLostCallbackLoadsExactWinnerAndDoesNotRegrantOrAcknowledgeOldAttempt()
        {
            var f=await Ready(new ControlledDispatcher());var identity=f.Setup.Puzzles.Puzzles[0].Identity;LocalSaveContractFixtures.Call(f.Use,"Start",identity,Guid.NewGuid());LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);SaveSnapshot<LocalProfileState>? committed=null;f.Repo.OnCommit=(s,g,ct)=>{committed=s;return Task.FromException<SaveCommitResult<LocalProfileState>>(new OperationCanceledException("Simulated lost callback after durable writer acknowledgement boundary"));};Assert.That((await f.Use.CommitCompletionAsync(CancellationToken.None)).Status,Is.EqualTo(SaveCommitStatus.RecoveryRequired));Assert.That(f.Use.CanPresentResults||f.Use.CanMutate,Is.False);Assert.That((await f.Use.CommitCompletionAsync(CancellationToken.None)).Status,Is.EqualTo(SaveCommitStatus.RecoveryRequired));Assert.That(f.Repo.Commits,Is.EqualTo(1));f.Repo.Loaded=SaveLoadResult<LocalProfileState>.Success(committed!,f.Setup.Observe(2,"e"));await f.Use.LoadAsync(CancellationToken.None);Assert.That(f.Use.Snapshot,Is.SameAs(committed));Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.Null);Assert.That(f.Use.CanPresentResults,Is.False);Assert.That(f.Setup.Ledger.Validate(f.Use.Snapshot!.Payload),Is.EqualTo(15));LocalSaveContractFixtures.Call(f.Use,"Start",identity,Guid.NewGuid());Assert.That(LocalSaveContractFixtures.Get(LocalSaveContractFixtures.Get(f.Use,"Session")!,"Mode")!.ToString(),Is.EqualTo("PRACTICE"));Assert.That(f.Repo.Commits,Is.EqualTo(1));
        }
        [Test]
        public async Task CommitConflictRequiresFreshChangedObservationAndASeparateExplicitRecoveryChoice()
        {
            var f=await Ready(new ControlledDispatcher());LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[0].Identity,Guid.NewGuid());LocalSaveContractFixtures.Mark(f.Use,f.Clock,100,"MARK_EMPTY",0);f.Repo.OnCommit=(s,g,ct)=>Task.FromResult(SaveCommitResult<LocalProfileState>.Failure(SaveCommitStatus.Conflict,"SAVE_GENERATION_CONFLICT"));var fresh=f.Setup.Observe(3,"d");f.Repo.OnLoad=ct=>Task.FromResult(SaveLoadResult<LocalProfileState>.Success(new SaveSnapshot<LocalProfileState>(f.Setup.Profile,f.Setup.Aggregate,3,f.Setup.Empty),fresh));var result=await f.Use.SaveDraftAsync(CancellationToken.None);Assert.That(result.Status,Is.EqualTo(SaveCommitStatus.Conflict));Assert.That(f.Repo.Loads,Is.EqualTo(2));Assert.That(f.Use.RecoveryObservation,Is.SameAs(fresh));Assert.That(f.Use.CanMutate,Is.False);Assert.That(f.Use.CanPresentResults,Is.False);await f.Use.LoadAsync(CancellationToken.None);Assert.That(f.Use.CanMutate,Is.False,"A second fresh load must not bypass the explicit choice required after conflict");var stale=new SaveRecoveryRequest(f.Setup.Observe(),SaveCandidateKind.Main);Assert.That((await f.Use.RecoverAsync(stale,CancellationToken.None)).Status,Is.EqualTo(SaveLoadStatus.Conflict));Assert.That(f.Repo.Recovers,Is.Zero);Assert.That((await f.Use.SaveDraftAsync(CancellationToken.None)).Status,Is.EqualTo(SaveCommitStatus.RecoveryRequired));Assert.That(f.Repo.Commits,Is.EqualTo(1));
        }
        [TestCase("Failed")][TestCase("Cancelled")][TestCase("AbsentObservation")]
        public async Task FailedCancelledOrIncompleteConflictReloadPreservesEveryEffectBlock(string kind)
        {
            var f=await Ready(new ControlledDispatcher());LocalSaveContractFixtures.Call(f.Use,"Start",f.Setup.Puzzles.Puzzles[0].Identity,Guid.NewGuid());LocalSaveContractFixtures.Mark(f.Use,f.Clock,100,"MARK_EMPTY",0);f.Repo.OnCommit=(s,g,ct)=>Task.FromResult(SaveCommitResult<LocalProfileState>.Failure(SaveCommitStatus.Conflict,"SAVE_GENERATION_CONFLICT"));f.Repo.OnLoad=ct=>kind=="Cancelled"?Task.FromException<SaveLoadResult<LocalProfileState>>(new OperationCanceledException()):Task.FromResult(kind=="Failed"?SaveLoadResult<LocalProfileState>.Failure(SaveLoadStatus.Failed,"SAVE_READ_FAILED"):SaveLoadResult<LocalProfileState>.Success(new SaveSnapshot<LocalProfileState>(f.Setup.Profile,f.Setup.Aggregate,1,f.Setup.Empty)));await f.Use.SaveDraftAsync(CancellationToken.None);Assert.That(f.Use.RecoveryObservation,Is.Null);Assert.That(f.Use.CanMutate||f.Use.CanPresentResults,Is.False);Assert.That((await f.Use.CommitCompletionAsync(CancellationToken.None)).Status,Is.EqualTo(SaveCommitStatus.RecoveryRequired));Assert.That(f.Repo.Commits,Is.EqualTo(1));
        }
        [TestCase(true)][TestCase(false)]
        public async Task ConfirmedWinnerFromAnotherAttemptReleasesOldSolvedAttemptWithoutClaimingItsAcknowledgement(bool conflict)
        {
            var f=await Ready(new ControlledDispatcher());var identity=f.Setup.Puzzles.Puzzles[0].Identity;LocalSaveContractFixtures.Call(f.Use,"Start",identity,Guid.NewGuid());LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);var losing=LocalSaveContractFixtures.Get(f.Use,"Session");var winner=f.Setup.Complete(f.Setup.Empty,f.Setup.Solved(0,"FIRST_RUN",900),2).State;var observation=f.Setup.Observe(2,"d");var loaded=SaveLoadResult<LocalProfileState>.Success(new SaveSnapshot<LocalProfileState>(f.Setup.Profile,f.Setup.Aggregate,2,winner),observation);f.Repo.OnCommit=(s,g,ct)=>Task.FromResult(SaveCommitResult<LocalProfileState>.Failure(conflict?SaveCommitStatus.Conflict:SaveCommitStatus.RecoveryRequired,"SAVE_UNCERTAIN"));f.Repo.OnLoad=ct=>Task.FromResult(loaded);await f.Use.CommitCompletionAsync(CancellationToken.None);Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.SameAs(losing));Assert.That(f.Use.CanPresentResults,Is.False);
            if(conflict){f.Repo.Loaded=loaded;var request=new SaveRecoveryRequest(observation,SaveCandidateKind.Main);Assert.That((await f.Use.RecoverAsync(request,CancellationToken.None)).Succeeded,Is.True);f.Repo.OnCommit=null;Assert.That((await f.Use.PromoteRecoveryAsync(CancellationToken.None)).Succeeded,Is.True);}else await f.Use.LoadAsync(CancellationToken.None);
            Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.Null);Assert.That(f.Use.CanPresentResults,Is.False);LocalSaveContractFixtures.Call(f.Use,"Start",identity,Guid.NewGuid());Assert.That(LocalSaveContractFixtures.Get(LocalSaveContractFixtures.Get(f.Use,"Session")!,"Mode")!.ToString(),Is.EqualTo("PRACTICE"));Assert.That(f.Use.CanPresentResults,Is.False);Assert.That(f.Use.CanMutate,Is.True);
        }
        [TestCase(true)][TestCase(false)]
        public async Task ExplicitNewProfileReleasesOldAttemptOnlyAfterConfirmedInitialization(bool succeeds)
        {
            var f=await Ready(new ControlledDispatcher());var identity=f.Setup.Puzzles.Puzzles[0].Identity;LocalSaveContractFixtures.Call(f.Use,"Start",identity,Guid.NewGuid());LocalSaveContractFixtures.SolveCurrent(f.Use,f.Clock);var old=LocalSaveContractFixtures.Get(f.Use,"Session");f.Repo.Loaded=SaveLoadResult<LocalProfileState>.NeedsInitialization();await f.Use.LoadAsync(CancellationToken.None);Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.SameAs(old));if(!succeeds)f.Repo.OnCommit=(s,g,ct)=>Task.FromResult(SaveCommitResult<LocalProfileState>.Failure(SaveCommitStatus.Failed,"SAVE_INITIALIZATION_FAILED"));var result=await f.Use.CreateProfileAsync(CancellationToken.None);Assert.That(result.Succeeded,Is.EqualTo(succeeds));Assert.That(f.Use.CanPresentResults,Is.False);if(succeeds){Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.Null);LocalSaveContractFixtures.Call(f.Use,"Start",identity,Guid.NewGuid());Assert.That(f.Use.CanMutate,Is.True);}else{Assert.That(LocalSaveContractFixtures.Get(f.Use,"Session"),Is.SameAs(old));Assert.That(f.Use.CanMutate,Is.False);}
        }
        private sealed class ThreadProbe : ICanonicalJson, ILocalSaveDispatcher, ILocalLedger
        {
            internal readonly ICanonicalJson InnerJson=LocalSaveContractFixtures.Json;internal ILocalLedger InnerLedger=null!;internal readonly int Caller=Thread.CurrentThread.ManagedThreadId;internal int HashCalls,LedgerCalls;private readonly AsyncLocal<bool> publication=new AsyncLocal<bool>();internal bool Armed;
            private void Check(){if(Armed){Assert.That(Thread.CurrentThread.ManagedThreadId,Is.Not.EqualTo(Caller),"Hash/ledger work ran inline on the caller thread");Assert.That(publication.Value,Is.False,"Hash/ledger work ran inside a UI publication");}}
            public CanonicalJsonResult Canonicalize(byte[] utf8,JsonResourceLimits limits){Check();if(Armed)Interlocked.Increment(ref HashCalls);return InnerJson.Canonicalize(utf8,limits);}
            public Task InvokeAsync(Action action){publication.Value=true;try{action();return Task.CompletedTask;}finally{publication.Value=false;}}
            public long Validate(LocalProfileState state){Check();if(Armed)Interlocked.Increment(ref LedgerCalls);return InnerLedger.Validate(state);}
            public LocalStoredEntry Next(LocalLedgerCheckpoint c,System.Collections.Generic.IReadOnlyList<LocalStoredEntry> j,EconomyTerminal t){Check();return InnerLedger.Next(c,j,t);}
            public LocalStoredEntry NextPurchase(LocalLedgerCheckpoint c,System.Collections.Generic.IReadOnlyList<LocalStoredEntry> j,PurchasedOwnership p){Check();return InnerLedger.NextPurchase(c,j,p);}
            public LocalProfileState Compact(LocalProfileState state,long generation){Check();if(Armed)Interlocked.Increment(ref LedgerCalls);return InnerLedger.Compact(state,generation);}
        }
        [Test]
        public void ImmediateRepositoryAndSemaphoreStillOffloadLoadNewProfileCompletionAndDraftHashing()
        {
            var s=new LocalSaveContractFixtures.Setup();var probe=new ThreadProbe();probe.InnerLedger=LocalSaveContractFixtures.Construct<ILocalLedger>("STP.Infrastructure.Persistence","STP.Infrastructure.Persistence.SaveLedgerCodec",probe);var policy=new LocalProgressPolicy(s.Puzzles,s.Campaign,s.Completion,probe,probe);var clock=new LocalSaveContractFixtures.Clock();var repo=new LocalSaveContractFixtures.Repository();var use=new PersistedPuzzleSession(repo,s.Puzzles,policy,s.Profile,s.Catalogs,clock,probe);probe.Armed=true;use.LoadAsync(CancellationToken.None).GetAwaiter().GetResult();use.CreateProfileAsync(CancellationToken.None).GetAwaiter().GetResult();int created=probe.HashCalls;Assert.That(created,Is.GreaterThan(0));use.LoadAsync(CancellationToken.None).GetAwaiter().GetResult(); // missing is still an explicit initialization state
            probe.Armed=false;repo.Loaded=SaveLoadResult<LocalProfileState>.Success(new SaveSnapshot<LocalProfileState>(s.Profile,s.Aggregate,1,s.Empty),s.Observe());probe.Armed=true;use.LoadAsync(CancellationToken.None).GetAwaiter().GetResult();Assert.That(probe.HashCalls,Is.GreaterThan(created));LocalSaveContractFixtures.Call(use,"Start",s.Puzzles.Puzzles[0].Identity,Guid.NewGuid());LocalSaveContractFixtures.Mark(use,clock,100,"MARK_EMPTY",0);use.SaveDraftAsync(CancellationToken.None).GetAwaiter().GetResult();LocalSaveContractFixtures.SolveCurrent(use,clock);use.CommitCompletionAsync(CancellationToken.None).GetAwaiter().GetResult();Assert.That(use.CanPresentResults,Is.True);Assert.That(probe.LedgerCalls,Is.GreaterThan(3));
        }
    }
}
